function duplexPagePlacement(cv){const {width:w,height:h}=NATIONAL_DUPLEX_SIZE_MM,aspect=cv.width/cv.height,boxAspect=w/h;let drawW=w,drawH=h;if(aspect>boxAspect)drawH=w/aspect;else drawW=h*aspect;return{x:(NATIONAL_A4_MM.width-drawW)/2,y:(NATIONAL_A4_MM.height-drawH)/2,width:drawW,height:drawH}}
function buildDuplexPdf(){if(!S.front||!S.back)throw new Error('يجب التقاط الوجه الأمامي والخلفي أولاً');if(!window.jspdf?.jsPDF)throw new Error('مكتبة PDF غير جاهزة');const pdf=new jspdf.jsPDF({orientation:'portrait',unit:'mm',format:'a4'});[S.front,S.back].forEach((face,i)=>{const canvas=printCanvas(face,2_000_000),pos=duplexPagePlacement(canvas);if(i)pdf.addPage('a4','portrait');pdf.addImage(canvas.toDataURL('image/jpeg',.94),'JPEG',pos.x,pos.y,pos.width,pos.height)});return pdf.output('datauristring')}
function saveDuplexPdf(){try{saveData('National_ID_Duplex_'+Date.now()+'.pdf','application/pdf',buildDuplexPdf());logOperation('pdf','حفظ وجهي الهوية على صفحتين متطابقتين')}catch(e){alert('تعذر حفظ PDF ذي الوجهين: '+String(e.message||e))}}
function printDuplex(){if(!window.Android?.printBase64)return alert('الطباعة المزدوجة تحتاج محرك PDF الأصلي في Android');try{Android.printBase64('National_ID_Duplex.pdf','application/pdf',buildDuplexPdf());logOperation('print','طلب طباعة وجهي الهوية منفصلين على صفحتين A4')}catch(e){alert('تعذرت طباعة وجهي الهوية: '+String(e.message||e))}}
function loadScript(src,test){return new Promise((res,rej)=>{if(test())return res();let s=document.createElement('script');s.src=src;s.onload=()=>test()?res():rej(new Error('لم تبدأ مكتبة عرض المستند بعد تحميلها: '+src));s.onerror=()=>rej(new Error('مكتبة عرض المستند غير مضمنة في نسخة Android: '+src));document.head.appendChild(s)})}
function docs(){$('natDocInput').value='';$('natDocInput').click()}
async function openDoc(f){if(!f)return;S.doc=f;S.docReady=false;let n=(f.name||'').toLowerCase();$('natDocTitle').textContent='📄 '+f.name;$('natDocView').innerHTML='جاري فتح الملف...';open('natDocModal');recent('فتح مستند',f.name,'');logOperation('open','فتح مستند: '+f.name);if(f.size>30*1024*1024){$('natDocView').textContent='حجم الملف أكبر من 30MB؛ العرض الداخلي محدود لحماية ذاكرة الهاتف. يمكنك حفظ الملف الأصلي وفتحه بتطبيق مختص.';return}try{if(n.endsWith('.pdf'))return renderPdf(f);if(n.endsWith('.docx'))return renderDocx(f);if(n.endsWith('.xlsx')||n.endsWith('.xls')||n.endsWith('.csv'))return renderSheet(f);if(n.endsWith('.txt')){let text=await f.text();if(S.doc===f){$('natDocView').textContent=text;S.docReady=true}return}if(String(f.type||'').startsWith('image/')){let d=await fileData(f);if(S.doc===f){$('natDocView').innerHTML=`<img src="${d}" style="max-width:100%">`;S.docReady=true}return}$('natDocView').innerHTML='<p>تم اختيار الملف. العرض الداخلي المباشر متاح لـ PDF وWord DOCX وExcel والصور والنصوص. يمكن حفظ/فتح الأنواع الأخرى من خلال تطبيقاتها.</p><p>'+escapeHtml(f.name)+'</p>'}catch(e){if(S.doc===f)$('natDocView').textContent='تعذر عرض الملف داخليًا: '+(e.message||e)}}
async function renderPdf(f){
 await loadScript('vendor/documents/pdf.min.js',()=>!!window.pdfjsLib);
 pdfjsLib.GlobalWorkerOptions.workerSrc='vendor/documents/pdf.worker.min.js';
 let pdf;
 try{
  const ab=await f.arrayBuffer();if(S.doc!==f)return;
  pdf=await pdfjsLib.getDocument({data:ab,isEvalSupported:false}).promise;
  if(S.doc!==f)return;
  const wrap=$('natDocView'),pageCount=Math.min(pdf.numPages,20),maxPixels=Math.min(4_000_000,Math.floor(24_000_000/Math.max(1,pageCount)));
  wrap.innerHTML='';
  for(let i=1;i<=pageCount;i++){
   if(S.doc!==f)return;
   const page=await pdf.getPage(i),first=page.getViewport({scale:1.25}),scale=1.25*Math.min(1,Math.sqrt(maxPixels/Math.max(1,first.width*first.height))),vp=page.getViewport({scale}),canvas=document.createElement('canvas');
   canvas.width=Math.max(1,Math.floor(vp.width));canvas.height=Math.max(1,Math.floor(vp.height));
   const ctx=canvas.getContext('2d');if(!ctx)throw new Error('ذاكرة عرض PDF غير متاحة');
   await page.render({canvasContext:ctx,viewport:vp}).promise;
   if(S.doc!==f)return;
   wrap.appendChild(canvas);page.cleanup?.()
  }
  if(pdf.numPages>20&&S.doc===f){const note=document.createElement('p');note.textContent='المعاينة تعرض أول 20 صفحة لتقليل استخدام الذاكرة؛ ملف PDF الأصلي محفوظ بكامل صفحاته ويمكن طباعته بالكامل.';wrap.appendChild(note)}
  if(S.doc===f)S.docReady=true
 }finally{if(pdf)await pdf.destroy?.()}
}
function safeDocumentHtml(html){
  const parsed=new DOMParser().parseFromString(String(html||''),'text/html'),out=document.createElement('div');
  const allow=new Set(['P','DIV','BR','SPAN','STRONG','EM','B','I','U','S','DEL','SUB','SUP','H1','H2','H3','H4','H5','H6','TABLE','THEAD','TBODY','TFOOT','TR','TD','TH','UL','OL','LI','BLOCKQUOTE','PRE','CODE','A','IMG','HR']);
  const block=new Set(['SCRIPT','STYLE','IFRAME','OBJECT','EMBED','SVG','MATH','FORM','META','BASE','LINK','INPUT','BUTTON','TEMPLATE','VIDEO','AUDIO']);
  function copy(node,parent){
    if(node.nodeType===3){parent.appendChild(document.createTextNode(node.textContent||''));return}
    if(node.nodeType!==1||block.has(node.tagName))return;
    let tag=allow.has(node.tagName)?node.tagName.toLowerCase():'span',child=document.createElement(tag);
    if(tag==='a'){let href=String(node.getAttribute('href')||'').trim();if(/^(https?:\/\/|mailto:|tel:|#)/i.test(href)){child.setAttribute('href',href);child.setAttribute('rel','noopener noreferrer')}}
    if(tag==='img'){let src=String(node.getAttribute('src')||'');if(/^data:image\/(png|jpeg|webp);base64,[A-Za-z0-9+/=]+$/i.test(src)&&src.length<8000000)child.setAttribute('src',src);else return}
    if(tag==='td'||tag==='th'){for(const a of ['colspan','rowspan']){let v=Number(node.getAttribute(a));if(Number.isInteger(v)&&v>=1&&v<=20)child.setAttribute(a,String(v))}}
    for(const n of [...node.childNodes])copy(n,child);
    parent.appendChild(child)
  }
  for(const node of [...parsed.body.childNodes])copy(node,out);
  return out.innerHTML
}
async function renderDocx(f){await loadScript('vendor/documents/mammoth.browser.min.js',()=>!!window.mammoth);let r=await mammoth.convertToHtml({arrayBuffer:await f.arrayBuffer()});if(S.doc===f){$('natDocView').innerHTML=safeDocumentHtml(r.value);S.docReady=true}}
async function renderSheet(f){await loadScript('vendor/documents/xlsx.full.min.js',()=>!!window.XLSX);let wb=XLSX.read(await f.arrayBuffer(),{type:'array'}),name=wb.SheetNames[0],html=XLSX.utils.sheet_to_html(wb.Sheets[name]);if(S.doc===f){$('natDocView').innerHTML=safeDocumentHtml(html);S.docReady=true}}
function escapeHtml(s){return String(s).replace(/[&<>]/g,m=>({'&':'&amp;','<':'&lt;','>':'&gt;'}[m]))}
function htmlForOpenDoc(){return `<!doctype html><html dir="auto"><head><meta charset="utf-8"><style>@page{size:A4;margin:12mm}body{font-family:Tahoma,Arial;line-height:1.7}table{border-collapse:collapse;width:100%}td,th{border:1px solid #777;padding:4px}img,canvas{max-width:100%}</style></head><body>${$('natDocView').innerHTML}</body></html>`}
async function saveOpenDoc(){let f=S.doc,epoch=nationalSessionEpoch;if(!f)return alert('افتح مستنداً أولاً');let data=await fileData(f);if(epoch!==nationalSessionEpoch||S.doc!==f)return;saveData(f.name,f.type||'application/octet-stream',data);logOperation('save','حفظ الأصل: '+f.name)}
async function galleryOpenDoc(){let f=S.doc,epoch=nationalSessionEpoch;if(!f)return alert('افتح مستنداً أولاً');if(!String(f.type||'').startsWith('image/'))return saveOpenDoc();let data=await fileData(f);if(epoch!==nationalSessionEpoch||S.doc!==f)return;saveImage(f.name,f.type,data);logOperation('gallery','حفظ المستند الصوري في المعرض: '+f.name,'',data)}
function pdfFromImage(data,name){if(!window.jspdf?.jsPDF)throw new Error('محرك PDF غير جاهز');return new Promise((resolve,reject)=>{let image=new Image();image.onload=()=>{try{let w=image.naturalWidth||image.width,h=image.naturalHeight||image.height;if(!w||!h)throw new Error('أبعاد الصورة غير صالحة');let scale=Math.min(1,Math.sqrt(6_000_000/(w*h))),canvas=document.createElement('canvas');canvas.width=Math.max(1,Math.floor(w*scale));canvas.height=Math.max(1,Math.floor(h*scale));let ctx=canvas.getContext('2d');ctx.fillStyle='#fff';ctx.fillRect(0,0,canvas.width,canvas.height);ctx.drawImage(image,0,0,canvas.width,canvas.height);let doc=new jspdf.jsPDF({unit:'mm',format:'a4'}),iw=190,ih=iw*canvas.height/canvas.width;if(ih>277){ih=277;iw=ih*canvas.width/canvas.height}doc.addImage(canvas.toDataURL('image/jpeg',.9),'JPEG',(210-iw)/2,(297-ih)/2,iw,ih);resolve(doc.output('datauristring'))}catch(e){reject(e)}};image.onerror=()=>reject(new Error('تعذر قراءة الصورة'));image.src=data})}
async function pdfOpenDoc(){let f=S.doc,epoch=nationalSessionEpoch;if(!f)return alert('افتح مستنداً أولاً');try{let data=await fileData(f),name=f.name.replace(/\.[^.]+$/,'')+'.pdf';if(epoch!==nationalSessionEpoch||S.doc!==f)return;if(/\.pdf$/i.test(f.name))saveData(name,'application/pdf',data);else if(String(f.type||'').startsWith('image/')){let pdf=await pdfFromImage(data,name);if(epoch!==nationalSessionEpoch||S.doc!==f)return;saveData(name,'application/pdf',pdf)}else if(/\.(docx|xlsx?|csv|txt)$/i.test(f.name)&&S.docReady&&S.doc===f&&window.Android&&Android.savePdfHtml)Android.savePdfHtml(name,htmlForOpenDoc());else throw new Error('لا يمكن تحويل هذا الملف: افتحه وانتظر اكتمال المعاينة، أو استخدم تطبيقًا يدعم هذا النوع من المستندات.');logOperation('pdf','حفظ المستند PDF: '+f.name)}catch(e){if(epoch===nationalSessionEpoch&&S.doc===f)alert(e.message||'تعذر إنشاء PDF')}}
async function printOpenDoc(){let f=S.doc,epoch=nationalSessionEpoch;if(!f)return alert('افتح مستنداً أولاً');try{let data=await fileData(f);if(epoch!==nationalSessionEpoch||S.doc!==f)return;if(String(f.type||'').startsWith('image/')){if(window.Android&&Android.printPages)Android.printPages(JSON.stringify([data]),'A4',0);else throw new Error('الطباعة متاحة داخل Android')}else if(/\.pdf$/i.test(f.name)){if(window.Android&&Android.printBase64)Android.printBase64(f.name,f.type||'application/pdf',data);else throw new Error('الطباعة متاحة داخل Android')}else if(/\.(docx|xlsx?|csv|txt)$/i.test(f.name)&&S.docReady&&S.doc===f&&window.Android&&Android.printHtml)Android.printHtml(htmlForOpenDoc());else throw new Error('انتظر اكتمال معاينة المستند أو افتحه ببرنامج يدعم نوعه قبل الطباعة.');logOperation('print','طباعة المستند: '+f.name)}catch(e){if(epoch===nationalSessionEpoch&&S.doc===f)alert(e.message||'تعذرت الطباعة')}}
